CREATE TABLE IDEMPOTENCY_RECORD (RECORD_ID VARCHAR2(36) PRIMARY KEY, IDEMPOTENCY_SCOPE VARCHAR2(100) NOT NULL, KEY_HASH VARCHAR2(64) NOT NULL, REQUEST_HASH VARCHAR2(64) NOT NULL, RESOURCE_ID VARCHAR2(36), CREATED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT UQ_BILL_IDEMPOTENCY UNIQUE (IDEMPOTENCY_SCOPE, KEY_HASH));
